82	func runMigrateCheckpointsV2(ctx context.Context, cmd *cobra.Command, force bool) error {
83		repo, err := strategy.OpenRepository(ctx)
84		if err != nil {
85			cmd.SilenceUsage = true
86			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
87			return NewSilentError(err)
88		}
89	
90		v1Store := checkpoint.NewGitStore(repo)
91		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
92		out := cmd.OutOrStdout()
93		progressOut := cmd.ErrOrStderr()
94	
95		result, err := migrateCheckpointsV2(ctx, repo, v1Store, v2Store, progressOut, force)
96		if err != nil {
97			return err
98		}
99	
100		stopRepair := startSpinner(cmd.ErrOrStderr(), "Repairing archived generation metadata")
101		repairResult, repairErr := strategy.RepairV2GenerationMetadata(ctx)
102		stopRepair("")
103		if repairErr != nil {
104			return fmt.Errorf("failed to repair archived v2 generation metadata: %w", repairErr)
105		}
106		printV2GenerationRepairResult(out, cmd.ErrOrStderr(), repairResult)
107	
108		printMigrateCompletion(out, result)
109		fmt.Fprintln(out, "Note: V2 checkpoints are stored as custom refs under refs/entire/checkpoints/v2/*, not as a branch visible in the GitHub UI.")
110		fmt.Fprintf(out, "To inspect pushed v2 checkpoint refs locally, run: git ls-remote %s \"refs/entire/checkpoints/v2/*\"\n", migrateRemoteName)
111		fmt.Fprintln(out, `You may also open a checkpoint's details in the Entire web app and click the "session logs" link to view the log files and metadata.`)
112	
113		if result.failed > 0 {
114			return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
115		}
116		if repairResult != nil && len(repairResult.Failed) > 0 {
117			fmt.Fprintf(out, "%d archived generation(s) failed metadata repair. Check warnings above for details.\n", len(repairResult.Failed))
118			return NewSilentError(fmt.Errorf("%d archived generation(s) failed metadata repair", len(repairResult.Failed)))
119		}
120	
121		return nil
122	}
