126	func printMigrateCompletion(out io.Writer, result *migrateResult) {
127		if result.total == 0 {
128			fmt.Fprintln(out, "Nothing to migrate: no v1 checkpoints found")
129			fmt.Fprintln(out)
130			return
131		}
132	
133		fmt.Fprintf(out, "Migration complete: %d migrated, %d skipped, %d failed\n",
134			result.migrated, result.skipped, result.failed)
135	
136		if result.hasLoggedDetails() {
137			fmt.Fprintf(out, "Details for skipped, missing, incomplete, or failed checkpoints were logged to %s.\n", migrationLogFile)
138		}
139	
140		fmt.Fprintln(out)
141	}
