190	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, progressOut io.Writer, force bool) (*migrateResult, error) {
191		v1List, err := v1Store.ListCommitted(ctx)
192		if err != nil {
193			return nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
194		}
195	
196		if len(v1List) == 0 {
197			return &migrateResult{}, nil
198		}
199	
200		sortMigratableCheckpoints(v1List)
201		total := len(v1List)
202		result := &migrateResult{total: total}
203		progress := startProgressBar(progressOut, "Migrating checkpoints", total)
204		defer progress.Finish()
205	
206		_, fullCurrentRefErr := repo.Reference(plumbing.ReferenceName(paths.V2FullCurrentRefName), true)
207		fullCurrentExistsBefore := fullCurrentRefErr == nil
208	
209		packer := newGenerationPacker(repo, v2Store)
210	
211		for _, info := range v1List {
212			fullCheckpoint, outcome, migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, force)
213			result.missingSessions += outcome.missingSessions
214			result.backfilledCompactTranscripts += outcome.backfilledCompactTranscripts
215			if outcome.compactTranscriptSkipped {
216				result.compactTranscriptSkipped++
217			}
218			if outcome.repaired {
219				result.repaired++
220			}
221	
222			if migrateErr != nil {
223				switch {
224				case errors.Is(migrateErr, errAlreadyMigrated):
225					logCheckpointMigrationSkip(ctx, info.CheckpointID, "already in v2", migrateErr)
226					result.skipped++
227				case errors.Is(migrateErr, errTranscriptNotGeneratable):
228					logCheckpointMigrationSkip(ctx, info.CheckpointID, "transcript.jsonl could not be generated", migrateErr)
229					result.skipped++
230				case errors.Is(migrateErr, errNoMigratableSessions):
231					logCheckpointMigrationSkip(ctx, info.CheckpointID, "no migratable v1 sessions", migrateErr)
232					result.skipped++
233				case errors.Is(migrateErr, errNoFullPackingNeeded):
234					result.migrated++
235				default:
236					logging.Error(ctx, "checkpoint migration failed",
237						slog.String("checkpoint_id", string(info.CheckpointID)),
238						slog.String("error", migrateErr.Error()),
239					)
240					result.failed++
241				}
242				progress.Increment()
243				continue
244			}
245	
246			if fullCheckpoint != nil {
247				if packErr := packer.add(ctx, *fullCheckpoint); packErr != nil {
248					return result, fmt.Errorf("failed to pack migrated raw transcripts: %w", packErr)
249				}
250			}
251			result.migrated++
252			progress.Increment()
253		}
254	
255		stopFinalize := startSpinner(progressOut, "Packing migrated raw transcripts")
256		if err := packer.finalize(ctx, !fullCurrentExistsBefore); err != nil {
257			stopFinalize("")
258			return result, fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
259		}
260		stopFinalize("")
261	
262		return result, nil
263	}
