265	func logCheckpointMigrationSkip(ctx context.Context, checkpointID id.CheckpointID, reason string, err error) {
266		logging.Info(ctx, "checkpoint migration skipped",
267			slog.String("checkpoint_id", string(checkpointID)),
268			slog.String("reason", reason),
269			slog.String("error", err.Error()),
270		)
271	}
