273	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
274		sort.SliceStable(checkpoints, func(i, j int) bool {
275			left := checkpoints[i].CreatedAt
276			right := checkpoints[j].CreatedAt
277			switch {
278			case left.IsZero() && right.IsZero():
279				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
280			case left.IsZero():
281				return false
282			case right.IsZero():
283				return true
284			case left.Equal(right):
285				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
286			default:
287				return left.Before(right)
288			}
289		})
290	}
