299	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
300		var outcome migrateCheckpointOutcome
301	
302		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
303		if err != nil {
304			return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
305		}
306	
307		if existing != nil && !force {
308			// Fast-path: when every session already has a compact transcript and
309			// /full/<n> artifacts, the repair branch below is a guaranteed no-op.
310			if v2CheckpointFullyMigrated(v2Store, info, existing) {
311				return nil, outcome, errAlreadyMigrated
312			}
313	
314			fullCheckpoint, queuedFullRepair, repairErr := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing)
315			if repairErr != nil {
316				return nil, outcome, repairErr
317			}
318			outcome.repaired = queuedFullRepair
319	
320			currentV2, readCurrentErr := v2Store.ReadCommitted(ctx, info.CheckpointID)
321			if readCurrentErr != nil {
322				return nil, outcome, fmt.Errorf("failed to re-read v2 checkpoint %s: %w", info.CheckpointID, readCurrentErr)
323			}
324			if currentV2 == nil {
325				return nil, outcome, fmt.Errorf("v2 checkpoint %s disappeared during migration", info.CheckpointID)
326			}
327	
328			// Clean up v1-named transcript files (full.jsonl, content_hash.txt) that older
329			// CLI versions may have written to /full/current before the rename to raw_transcript.
330			cleanupV1TranscriptFiles(ctx, repo, v2Store, info.CheckpointID, len(currentV2.Sessions))
331	
332			backfilled, backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, currentV2)
333			outcome.backfilledCompactTranscripts = backfilled
334			if !queuedFullRepair {
335				if backfillErr != nil {
336					return nil, outcome, backfillErr
337				}
338				return nil, outcome, errNoFullPackingNeeded
339			}
340			if errors.Is(backfillErr, errTranscriptNotGeneratable) {
341				outcome.compactTranscriptSkipped = true
342			}
343			if backfillErr != nil &&
344				!errors.Is(backfillErr, errAlreadyMigrated) &&
345				!errors.Is(backfillErr, errTranscriptNotGeneratable) {
346				return nil, outcome, backfillErr
347			}
348			return fullCheckpoint, outcome, nil
349		}
350	
351		if existing != nil && force {
352			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
353				return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
354			}
355		}
356	
357		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
358		if err != nil {
359			return nil, outcome, fmt.Errorf("failed to read v1 summary: %w", err)
360		}
361		if summary == nil {
362			return nil, outcome, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
363		}
364	
365		compactFailed := false
366		shouldCopyTaskMetadata := false
367		skippedMissingSessions := 0
368		migratedSessions := 0
369		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
370		fullCheckpoint := &migratedFullCheckpoint{
371			checkpointID: info.CheckpointID,
372		}
373	
374		for sessionIdx := range len(summary.Sessions) {
375			content, skipped, readErr := readV1SessionForMigration(ctx, v1Store, info.CheckpointID, sessionIdx)
376			if skipped {
377				skippedMissingSessions++
378				outcome.missingSessions++
379				continue
380			}
381			if readErr != nil {
382				return nil, outcome, fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
383			}
384			if content.Metadata.IsTask {
385				shouldCopyTaskMetadata = true
386			}
387	
388			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
389	
390			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
391			if compacted != nil {
392				opts.CompactTranscript = compacted
393				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
394			} else if len(content.Transcript) > 0 {
395				compactFailed = true
396			}
397	
398			mainOpts := opts
399			mainOpts.Transcript = redact.AlreadyRedacted(nil)
400			v2SessionIdx, writeErr := v2Store.WriteCommittedWithSessionIndex(ctx, mainOpts)
401			if writeErr != nil {
402				return nil, outcome, fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
403			}
404			v1ToV2SessionIdx[sessionIdx] = v2SessionIdx
405			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
406				sessionIndex: v2SessionIdx,
407				content:      content,
408			})
409			migratedSessions++
410		}
411	
412		if migratedSessions == 0 {
413			return nil, outcome, fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
414		}
415	
416		if shouldCopyTaskMetadata {
417			taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, summary, v1ToV2SessionIdx)
418			if taskErr != nil {
419				logging.Warn(ctx, "failed to copy task metadata to v2",
420					slog.String("checkpoint_id", string(info.CheckpointID)),
421					slog.String("error", taskErr.Error()),
422				)
423			} else {
424				fullCheckpoint.taskTrees = taskTrees
425			}
426		}
427	
428		if compactFailed {
429			outcome.compactTranscriptSkipped = true
430			logging.Warn(ctx, "compact transcript not generated during checkpoint migration",
431				slog.String("checkpoint_id", string(info.CheckpointID)),
432				slog.Int("migrated_sessions", migratedSessions),
433			)
434		}
435		if skippedMissingSessions > 0 {
436			logging.Warn(ctx, "checkpoint migration skipped v1 sessions with missing transcript/session content",
437				slog.String("checkpoint_id", string(info.CheckpointID)),
438				slog.Int("missing_sessions", skippedMissingSessions),
439			)
440		}
441	
442		return fullCheckpoint, outcome, nil
443	}
