445	// generationPacker buffers up to batchSize migrated checkpoints and flushes
446	// them into a single archived /full/<n> ref each time the buffer fills, so
447	// peak heap stays bounded by one batch worth of transcripts instead of
448	// growing with the total v1 list. The next generation number is resolved
449	// lazily on first flush so force-migration prune steps that remove existing
450	// archived refs are visible before we pick the next slot.
451	type generationPacker struct {
452		repo           *git.Repository
453		v2Store        *checkpoint.V2GitStore
454		batchSize      int
455		nextGeneration int
456		numbered       bool
457		pending        []migratedFullCheckpoint
458		flushed        bool
459	}
460	
461	func newGenerationPacker(repo *git.Repository, v2Store *checkpoint.V2GitStore) *generationPacker {
462		batchSize := migrateMaxCheckpointsPerGeneration
463		if batchSize <= 0 {
464			batchSize = checkpoint.DefaultMaxCheckpointsPerGeneration
465		}
466		return &generationPacker{
467			repo:      repo,
468			v2Store:   v2Store,
469			batchSize: batchSize,
470		}
471	}
472	
473	func (p *generationPacker) add(ctx context.Context, cp migratedFullCheckpoint) error {
474		p.pending = append(p.pending, cp)
475		if len(p.pending) >= p.batchSize {
476			return p.flush(ctx)
477		}
478		return nil
479	}
480	
481	func (p *generationPacker) flush(ctx context.Context) error {
482		if len(p.pending) == 0 {
483			return nil
484		}
485		if !p.numbered {
486			next, err := p.v2Store.NextGenerationNumber()
487			if err != nil {
488				return fmt.Errorf("list archived v2 generations: %w", err)
489			}
490			p.nextGeneration = next
491			p.numbered = true
492		}
493		refName := plumbing.ReferenceName(fmt.Sprintf("%s%013d", paths.V2FullRefPrefix, p.nextGeneration))
494		if err := writeMigratedFullGeneration(ctx, p.repo, refName, p.pending); err != nil {
495			return err
496		}
497		p.nextGeneration++
498		p.pending = nil
499		p.flushed = true
500		return nil
501	}
502	
503	func (p *generationPacker) finalize(ctx context.Context, ensureEmptyCurrent bool) error {
504		if err := p.flush(ctx); err != nil {
505			return err
506		}
507		if p.flushed && ensureEmptyCurrent {
508			return ensureEmptyV2FullCurrent(ctx, p.repo)
509		}
510		return nil
511	}
512	
513	func writeMigratedFullGeneration(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, checkpoints []migratedFullCheckpoint) error {
514		entries := make(map[string]object.TreeEntry)
515	
516		for _, cp := range checkpoints {
517			for _, session := range cp.sessions {
518				if err := writeMigratedFullSessionEntries(ctx, repo, cp, session, entries); err != nil {
519					return fmt.Errorf("write full session entries for checkpoint %s session %d: %w", cp.checkpointID, session.sessionIndex, err)
520				}
521			}
522		}
523	
524		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
525		if err != nil {
526			return fmt.Errorf("build migrated generation tree: %w", err)
527		}
528	
529		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
530		// Prefer the in-memory transcripts we already loaded during migration —
531		// it produces the same first-event/last-event range as walking the just-
532		// written /full/<n> tree, but skips the redundant git blob reads that
533		// dominated runtime when this called ComputeGenerationTimestampsFromTrees.
534		gen, found := checkpoint.AggregateTranscriptTimestamps(migratedTranscripts(checkpoints))
535		if !found {
536			var err error
537			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
538			if err != nil {
539				return fmt.Errorf("compute checkpoint timestamps: %w", err)
540			}
541		}
542		if !found {
543			gen, found = generationMetadataFromMigratedSessions(checkpoints)
544		}
545		if !found {
546			return fmt.Errorf("no timestamps found for migrated generation %s", refName)
547		}
548	
549		treeHash, err = v2Store.AddGenerationJSONToTree(treeHash, gen)
550		if err != nil {
551			return fmt.Errorf("add generation metadata: %w", err)
552		}
553	
554		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, plumbing.ZeroHash,
555			fmt.Sprintf("Archive migrated generation: %s\n", refName),
556			migrateAuthorName, migrateAuthorEmail)
557		if err != nil {
558			return fmt.Errorf("create migrated generation commit: %w", err)
559		}
560	
561		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
562			return fmt.Errorf("update migrated generation ref %s: %w", refName, err)
563		}
564		return nil
565	}
