567	// migratedTranscripts returns the in-memory transcript bytes for every session
568	// already loaded during this migration run, in iteration order.
569	func migratedTranscripts(checkpoints []migratedFullCheckpoint) [][]byte {
570		var transcripts [][]byte
571		for _, cp := range checkpoints {
572			for _, session := range cp.sessions {
573				if len(session.content.Transcript) == 0 {
574					continue
575				}
576				transcripts = append(transcripts, session.content.Transcript)
577			}
578		}
579		return transcripts
580	}
