593	func writeMigratedFullSessionEntries(ctx context.Context, repo *git.Repository, cp migratedFullCheckpoint, session migratedFullSession, entries map[string]object.TreeEntry) error {
594		sessionPath := fmt.Sprintf("%s/%d/", cp.checkpointID.Path(), session.sessionIndex)
595		transcript := session.content.Transcript
596	
597		chunks, err := agent.ChunkTranscript(ctx, transcript, session.content.Metadata.Agent)
598		if err != nil {
599			return fmt.Errorf("chunk transcript: %w", err)
600		}
601		for i, chunk := range chunks {
602			blobHash, blobErr := checkpoint.CreateBlobFromContent(repo, chunk)
603			if blobErr != nil {
604				return fmt.Errorf("create transcript blob: %w", blobErr)
605			}
606			path := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
607			entries[path] = object.TreeEntry{
608				Name: path,
609				Mode: filemode.Regular,
610				Hash: blobHash,
611			}
612		}
613	
614		hashPath := sessionPath + paths.V2RawTranscriptHashFileName
615		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
616		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(contentHash))
617		if err != nil {
618			return fmt.Errorf("create transcript hash blob: %w", err)
619		}
620		entries[hashPath] = object.TreeEntry{
621			Name: hashPath,
622			Mode: filemode.Regular,
623			Hash: hashBlob,
624		}
625	
626		for _, taskTreeHash := range cp.taskTrees[session.sessionIndex] {
627			taskTree, treeErr := repo.TreeObject(taskTreeHash)
628			if treeErr != nil {
629				return fmt.Errorf("read task metadata tree: %w", treeErr)
630			}
631			taskEntries := make(map[string]object.TreeEntry)
632			if flattenErr := checkpoint.FlattenTree(repo, taskTree, sessionPath+"tasks", taskEntries); flattenErr != nil {
633				return fmt.Errorf("flatten task metadata tree: %w", flattenErr)
634			}
635			for path, entry := range taskEntries {
636				if _, exists := entries[path]; exists {
637					continue
638				}
639				entries[path] = entry
640			}
641		}
642	
643		return nil
644	}
