714	func pruneV2CheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
715		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
716		if err != nil {
717			if errors.Is(err, plumbing.ErrReferenceNotFound) {
718				return nil
719			}
720			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
721		}
722	
723		rootTree, err := repo.TreeObject(rootTreeHash)
724		if err != nil {
725			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
726		}
727		if _, err := rootTree.Tree(cpID.Path()); err != nil {
728			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
729		}
730	
731		shardPrefix := string(cpID[:2])
732		shardSuffix := string(cpID[2:])
733		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
734		if err != nil {
735			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
736		}
737		if newRoot == rootTreeHash {
738			return nil
739		}
740	
741		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
742			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
743			migrateAuthorName, migrateAuthorEmail)
744		if err != nil {
745			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
746		}
747	
748		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
749			return fmt.Errorf("failed to update ref %s: %w", refName, err)
750		}
751		return nil
752	}
