754	func pruneV2ArchivedCheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
755		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
756		if err != nil {
757			if errors.Is(err, plumbing.ErrReferenceNotFound) {
758				return nil
759			}
760			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
761		}
762	
763		rootTree, err := repo.TreeObject(rootTreeHash)
764		if err != nil {
765			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
766		}
767		if _, err := rootTree.Tree(cpID.Path()); err != nil {
768			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
769		}
770	
771		shardPrefix := string(cpID[:2])
772		shardSuffix := string(cpID[2:])
773		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
774		if err != nil {
775			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
776		}
777		if newRoot == rootTreeHash {
778			return nil
779		}
780	
781		count, err := v2Store.CountCheckpointsInTree(newRoot)
782		if err != nil {
783			return fmt.Errorf("failed to count checkpoints in pruned %s: %w", refName, err)
784		}
785		if count == 0 {
786			if err := repo.Storer.RemoveReference(refName); err != nil {
787				return fmt.Errorf("failed to remove empty archived v2 generation %s: %w", refName, err)
788			}
789			return nil
790		}
791	
792		newRoot, err = addRecomputedGenerationJSON(v2Store, newRoot)
793		if err != nil {
794			return fmt.Errorf("failed to recompute generation metadata for %s: %w", refName, err)
795		}
796	
797		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
798			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
799			migrateAuthorName, migrateAuthorEmail)
800		if err != nil {
801			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
802		}
803	
804		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
805			return fmt.Errorf("failed to update ref %s: %w", refName, err)
806		}
807		return nil
808	}
