810	func addRecomputedGenerationJSON(v2Store *checkpoint.V2GitStore, treeHash plumbing.Hash) (plumbing.Hash, error) {
811		gen, found, err := v2Store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
812		if err != nil {
813			return plumbing.ZeroHash, fmt.Errorf("compute raw transcript timestamps: %w", err)
814		}
815		if !found {
816			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
817			if err != nil {
818				return plumbing.ZeroHash, fmt.Errorf("compute checkpoint timestamps: %w", err)
819			}
820		}
821		if !found {
822			return treeHash, nil
823		}
824	
825		newTreeHash, err := v2Store.AddGenerationJSONToTree(treeHash, gen)
826		if err != nil {
827			return plumbing.ZeroHash, fmt.Errorf("add generation metadata: %w", err)
828		}
829		return newTreeHash, nil
830	}
831	
832	func pruneCheckpointFromRoot(repo *git.Repository, rootTreeHash plumbing.Hash, shardPrefix, shardSuffix string) (plumbing.Hash, error) {
833		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
834			[]string{shardPrefix},
835			nil,
836			checkpoint.UpdateSubtreeOptions{
837				MergeMode:   checkpoint.MergeKeepExisting,
838				DeleteNames: []string{shardSuffix},
839			},
840		)
841		if err != nil {
842			return plumbing.ZeroHash, fmt.Errorf("failed to prune checkpoint from shard: %w", err)
843		}
844		if newRoot == rootTreeHash {
845			return newRoot, nil
846		}
847	
848		newRootTree, err := repo.TreeObject(newRoot)
849		if err != nil {
850			return plumbing.ZeroHash, fmt.Errorf("failed to read pruned root tree: %w", err)
851		}
852		shardTree, err := newRootTree.Tree(shardPrefix)
853		if err != nil {
854			return newRoot, nil //nolint:nilerr // The shard prefix was already absent after pruning.
855		}
856		if len(shardTree.Entries) > 0 {
857			return newRoot, nil
858		}
859	
860		prunedRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
861			nil,
862			nil,
863			checkpoint.UpdateSubtreeOptions{
864				MergeMode:   checkpoint.MergeKeepExisting,
865				DeleteNames: []string{shardPrefix},
866			},
867		)
868		if err != nil {
869			return plumbing.ZeroHash, fmt.Errorf("failed to prune empty shard prefix: %w", err)
870		}
871		return prunedRoot, nil
872	}
