874	func collectMissingFullCheckpointForPacking(
875		ctx context.Context,
876		repo *git.Repository,
877		v1Store *checkpoint.GitStore,
878		v2Store *checkpoint.V2GitStore,
879		info checkpoint.CommittedInfo,
880		v2Summary *checkpoint.CheckpointSummary,
881	) (*migratedFullCheckpoint, bool, error) {
882		missingSessions, err := collectMissingFullSessionsForPacking(ctx, v2Store, info.CheckpointID, v2Summary)
883		if err != nil {
884			return nil, false, err
885		}
886		if len(missingSessions) == 0 {
887			return nil, false, nil
888		}
889	
890		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
891		if err != nil {
892			return nil, false, fmt.Errorf("failed to read v1 summary while checking v2 raw artifacts: %w", err)
893		}
894		if v1Summary == nil {
895			return nil, false, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
896		}
897	
898		v1BySessionID, err := collectV1SessionIndexesForPacking(ctx, v1Store, info.CheckpointID, v1Summary, missingSessions)
899		if err != nil {
900			return nil, false, err
901		}
902	
903		fullCheckpoint := &migratedFullCheckpoint{
904			checkpointID: info.CheckpointID,
905		}
906		v1ToV2SessionIdx := make(map[int]int)
907	
908		for _, missingSession := range missingSessions {
909			v1Session, ok, readErr := readV1SessionForMissingFullArtifact(ctx, v1Store, info.CheckpointID, v1Summary, v1BySessionID, missingSession)
910			if readErr != nil {
911				return nil, false, readErr
912			}
913			if !ok {
914				return nil, false, fmt.Errorf("failed to find v1 session for v2 session %d while checking raw artifacts", missingSession.sessionIndex)
915			}
916	
917			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
918				sessionIndex: missingSession.sessionIndex,
919				content:      v1Session.content,
920			})
921			v1ToV2SessionIdx[v1Session.sessionIndex] = missingSession.sessionIndex
922		}
923	
924		latestV2SessionIdx := len(v2Summary.Sessions) - 1
925		taskTrees, taskErr := collectTaskMetadataForMigratedFullGenerationWithRootSession(
926			repo,
927			info.CheckpointID,
928			v1Summary,
929			v1ToV2SessionIdx,
930			latestV2SessionIdx,
931			latestV2SessionIdx >= 0,
932		)
933		if taskErr != nil {
934			return nil, false, fmt.Errorf("failed to collect task metadata while checking raw artifacts: %w", taskErr)
935		}
936		fullCheckpoint.taskTrees = taskTrees
937	
938		return fullCheckpoint, true, nil
939	}
