951	func collectMissingFullSessionsForPacking(
952		ctx context.Context,
953		v2Store *checkpoint.V2GitStore,
954		checkpointID id.CheckpointID,
955		summary *checkpoint.CheckpointSummary,
956	) ([]missingFullSessionForPacking, error) {
957		missingSessions := make([]missingFullSessionForPacking, 0)
958		for sessionIdx := range len(summary.Sessions) {
959			ok, checkErr := hasFullSessionArtifacts(v2Store, checkpointID, sessionIdx)
960			if checkErr != nil {
961				return nil, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
962			}
963			if ok {
964				continue
965			}
966	
967			v2Content, readErr := v2Store.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIdx)
968			if readErr != nil {
969				return nil, fmt.Errorf("failed to read v2 session %d metadata while checking raw artifacts: %w", sessionIdx, readErr)
970			}
971	
972			missingSessions = append(missingSessions, missingFullSessionForPacking{
973				sessionIndex: sessionIdx,
974				sessionID:    v2Content.Metadata.SessionID,
975			})
976		}
977	
978		return missingSessions, nil
979	}
