981	func collectV1SessionIndexesForPacking(
982		ctx context.Context,
983		v1Store *checkpoint.GitStore,
984		checkpointID id.CheckpointID,
985		summary *checkpoint.CheckpointSummary,
986		missingSessions []missingFullSessionForPacking,
987	) (map[string][]int, error) {
988		neededSessionIDs := make(map[string]struct{})
989		for _, session := range missingSessions {
990			if session.sessionID != "" {
991				neededSessionIDs[session.sessionID] = struct{}{}
992			}
993		}
994	
995		bySessionID := make(map[string][]int)
996		if len(neededSessionIDs) == 0 {
997			return bySessionID, nil
998		}
999	
1000		for sessionIdx := range len(summary.Sessions) {
1001			metadata, err := v1Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1002			if err != nil {
1003				if ctxErr := ctx.Err(); ctxErr != nil {
1004					return nil, fmt.Errorf("context canceled while reading v1 session metadata: %w", ctxErr)
1005				}
1006				continue
1007			}
1008			if _, ok := neededSessionIDs[metadata.SessionID]; ok {
1009				bySessionID[metadata.SessionID] = append(bySessionID[metadata.SessionID], sessionIdx)
1010			}
1011		}
1012	
1013		return bySessionID, nil
1014	}
