1016	func readV1SessionForMissingFullArtifact(
1017		ctx context.Context,
1018		v1Store *checkpoint.GitStore,
1019		checkpointID id.CheckpointID,
1020		summary *checkpoint.CheckpointSummary,
1021		bySessionID map[string][]int,
1022		missingSession missingFullSessionForPacking,
1023	) (v1SessionForPacking, bool, error) {
1024		var triedSessionIndexes map[int]struct{}
1025		if missingSession.sessionID != "" {
1026			indexes := bySessionID[missingSession.sessionID]
1027			triedSessionIndexes = make(map[int]struct{}, len(indexes))
1028			for i := len(indexes) - 1; i >= 0; i-- {
1029				sessionIdx := indexes[i]
1030				triedSessionIndexes[sessionIdx] = struct{}{}
1031				session, found, err := readV1SessionForPacking(ctx, v1Store, checkpointID, sessionIdx)
1032				if err != nil || found {
1033					return session, found, err
1034				}
1035			}
1036		}
1037	
1038		if missingSession.sessionIndex >= len(summary.Sessions) {
1039			return v1SessionForPacking{}, false, nil
1040		}
1041		if _, tried := triedSessionIndexes[missingSession.sessionIndex]; tried {
1042			return v1SessionForPacking{}, false, nil
1043		}
1044		return readV1SessionForPacking(ctx, v1Store, checkpointID, missingSession.sessionIndex)
1045	}
