1047	func readV1SessionForPacking(
1048		ctx context.Context,
1049		v1Store *checkpoint.GitStore,
1050		checkpointID id.CheckpointID,
1051		sessionIdx int,
1052	) (v1SessionForPacking, bool, error) {
1053		content, err := v1Store.ReadSessionContent(ctx, checkpointID, sessionIdx)
1054		if err != nil {
1055			if errors.Is(err, checkpoint.ErrNoTranscript) || errors.Is(err, checkpoint.ErrCheckpointNotFound) {
1056				return v1SessionForPacking{}, false, nil
1057			}
1058			return v1SessionForPacking{}, false, fmt.Errorf("failed to read v1 session %d while checking raw artifacts: %w", sessionIdx, err)
1059		}
1060	
1061		return v1SessionForPacking{
1062			sessionIndex: sessionIdx,
1063			content:      content,
1064		}, true, nil
1065	}
