1075	// v2CheckpointFullyMigrated reports whether every session already has a compact
1076	// transcript and /full/<n> artifacts. Returns false on any uncertainty.
1077	func v2CheckpointFullyMigrated(v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, existing *checkpoint.CheckpointSummary) bool {
1078		if existing == nil || info.SessionCount == 0 || info.SessionCount != len(existing.Sessions) {
1079			return false
1080		}
1081		for i, session := range existing.Sessions {
1082			if session.Transcript == "" {
1083				return false
1084			}
1085			ok, err := hasFullSessionArtifacts(v2Store, info.CheckpointID, i)
1086			if err != nil || !ok {
1087				return false
1088			}
1089		}
1090		return true
1091	}
