1093	// backfillCompactTranscripts checks sessions in an already-migrated v2 checkpoint
1094	// for missing transcript.jsonl and attempts to generate + write them from v1 data.
1095	// Returns errAlreadyMigrated if all sessions already have compact transcripts.
1096	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (int, error) {
1097		// Find sessions missing transcript.jsonl
1098		var needsBackfill []int
1099		for i, session := range v2Summary.Sessions {
1100			if session.Transcript == "" {
1101				needsBackfill = append(needsBackfill, i)
1102			}
1103		}
1104	
1105		if len(needsBackfill) == 0 {
1106			return 0, errAlreadyMigrated
1107		}
1108	
1109		backfilled := 0
1110		var lastAgent string
1111	
1112		for _, sessionIdx := range needsBackfill {
1113			// Sessions with no agent type recorded in v2 are permanently
1114			// unrecoverable; skip without reading v1 to keep reruns cheap.
1115			if v2Meta, metaErr := v2Store.ReadSessionMetadataAndPrompts(ctx, info.CheckpointID, sessionIdx); metaErr == nil && v2Meta != nil && v2Meta.Metadata.Agent == "" {
1116				continue
1117			}
1118	
1119			content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
1120			if readErr != nil {
1121				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
1122					slog.String("checkpoint_id", string(info.CheckpointID)),
1123					slog.Int("session_index", sessionIdx),
1124					slog.String("error", readErr.Error()),
1125				)
1126				continue
1127			}
1128	
1129			if content.Metadata.Agent != "" {
1130				lastAgent = string(content.Metadata.Agent)
1131			}
1132	
1133			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
1134			if compacted == nil {
1135				// tryCompactTranscript already logs for no-agent and compact-error cases;
1136				// log the empty-transcript case here.
1137				if len(content.Transcript) == 0 {
1138					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
1139						slog.String("checkpoint_id", string(info.CheckpointID)),
1140						slog.Int("session_index", sessionIdx),
1141					)
1142				}
1143				continue
1144			}
1145	
