1221		}
1222	
1223		// transcript is read from persisted checkpoint storage and already redacted.
1224		compacted, err := compact.Compact(redact.AlreadyRedacted(transcript), compact.MetadataFields{
1225			Agent:      string(m.Agent),
1226			CLIVersion: versioninfo.Version,
1227			StartLine:  startLine,
1228		})
1229		if err != nil {
1230			logging.Warn(ctx, "compact transcript generation failed during migration",
1231				slog.String("checkpoint_id", string(m.CheckpointID)),
1232				slog.String("agent", string(m.Agent)),
1233				slog.String("error", err.Error()),
1234			)
1235			return nil
1236		}
1237		if len(compacted) == 0 {
1238			logging.Warn(ctx, "transcript.jsonl generation produced no output",
1239				slog.String("checkpoint_id", string(m.CheckpointID)),
1240				slog.String("agent", string(m.Agent)),
