1248	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
1249	// by comparing a full compact (startLine=0) against the scoped compact. The difference
1250	// is the number of compact lines before this checkpoint's data.
1251	func computeCompactOffset(ctx context.Context, fullTranscript, fullCompact []byte, m checkpoint.CommittedMetadata) int {
1252		startLine := m.GetTranscriptStart()
1253		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
1254			return 0
1255		}
1256	
1257		if len(fullCompact) == 0 {
1258			return 0
1259		}
1260	
1261		// fullTranscript is read from persisted checkpoint storage and already redacted.
1262		scopedCompact, err := compact.Compact(redact.AlreadyRedacted(fullTranscript), compact.MetadataFields{
1263			Agent:      string(m.Agent),
1264			CLIVersion: versioninfo.Version,
1265			StartLine:  startLine,
1266		})
1267		if err != nil {
1268			logging.Warn(ctx, "compact transcript offset calculation failed during migration",
1269				slog.String("checkpoint_id", string(m.CheckpointID)),
1270				slog.String("agent", string(m.Agent)),
1271				slog.String("error", err.Error()),
1272			)
1273			return 0
1274		}
1275		if len(scopedCompact) == 0 {
1276			return 0
1277		}
1278	
1279		fullLines := bytes.Count(fullCompact, []byte{'\n'})
1280		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
1281		offset := fullLines - scopedLines
1282		if offset < 0 {
1283			logging.Warn(ctx, "compact transcript offset was negative during migration, defaulting to 0",
1284				slog.String("checkpoint_id", string(m.CheckpointID)),
1285				slog.Int("full_lines", fullLines),
1286				slog.Int("scoped_lines", scopedLines),
1287			)
1288			return 0
1289		}
1290		return offset
1291	}
