1300		cpID id.CheckpointID,
1301		summary *checkpoint.CheckpointSummary,
1302		v1ToV2SessionIdx map[int]int,
1303		rootTaskV2SessionIdx int,
1304		attachRootTasks bool,
1305	) (map[int][]plumbing.Hash, error) {
1306		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
1307		if err != nil {
1308			return nil, err
1309		}
1310	
1311		taskTrees := make(map[int][]plumbing.Hash)
1312	
1313		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
1314		// Prefer attaching this tree to the latest session in v2.
1315		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
1316			if attachRootTasks {
1317				taskTrees[rootTaskV2SessionIdx] = append(taskTrees[rootTaskV2SessionIdx], rootTasksTree.Hash)
1318			}
1319		}
1320	
1321		for sessionIdx := range len(summary.Sessions) {
1322			sessionDir := strconv.Itoa(sessionIdx)
1323			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
1324			if sessionErr != nil {
1325				continue
1326			}
1327	
1328			tasksTree, tasksErr := sessionTree.Tree("tasks")
1329			if tasksErr != nil {
1330				continue
1331			}
1332	
1333			v2SessionIdx, ok := v1ToV2SessionIdx[sessionIdx]
1334			if !ok {
1335				continue
1336			}
1337			taskTrees[v2SessionIdx] = append(taskTrees[v2SessionIdx], tasksTree.Hash)
