108	func (s *V2GitStore) findFullSessionArtifacts(checkpointID id.CheckpointID, sessionIndex int) (fullSessionArtifacts, error) {
109		refNames, err := s.fullRefSearchOrder()
110		if err != nil {
111			return fullSessionArtifacts{}, err
112		}
113	
114		var firstFound fullSessionArtifacts
115		for _, refName := range refNames {
116			artifacts, inspectErr := s.inspectFullSessionArtifacts(refName, checkpointID, sessionIndex)
117			if inspectErr != nil {
118				return fullSessionArtifacts{}, inspectErr
119			}
120			if !artifacts.Found {
121				continue
122			}
123			if artifacts.HasTranscript && artifacts.HasHash {
124				return artifacts, nil
125			}
126			if !firstFound.Found {
127				firstFound = artifacts
128			}
129		}
130	
131		if firstFound.Found {
132			return firstFound, nil
133		}
134	
135		return fullSessionArtifacts{}, nil
136	}
