152	func (s *V2GitStore) inspectFullSessionArtifacts(refName plumbing.ReferenceName, checkpointID id.CheckpointID, sessionIndex int) (fullSessionArtifacts, error) {
153		_, rootTreeHash, err := s.GetRefState(refName)
154		if err != nil {
155			if errors.Is(err, plumbing.ErrReferenceNotFound) {
156				return fullSessionArtifacts{}, nil
157			}
158			return fullSessionArtifacts{}, err
159		}
160	
161		rootTree, err := s.repo.TreeObject(rootTreeHash)
162		if err != nil {
163			return fullSessionArtifacts{}, fmt.Errorf("failed to read %s tree: %w", refName, err)
164		}
165	
166		sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
167		sessionTree, err := rootTree.Tree(sessionPath)
168		if err != nil {
169			if errors.Is(err, object.ErrDirectoryNotFound) {
170				return fullSessionArtifacts{}, nil
171			}
172			return fullSessionArtifacts{}, fmt.Errorf("failed to read %s session tree %s: %w", refName, sessionPath, err)
173		}
174	
175		artifacts := fullSessionArtifacts{RefName: refName, Found: true}
176		for _, entry := range sessionTree.Entries {
177			switch {
178			case entry.Name == paths.V2RawTranscriptFileName:
179				artifacts.HasTranscript = true
180			case strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+"."):
181				artifacts.HasTranscript = true
182			case entry.Name == paths.V2RawTranscriptHashFileName:
183				artifacts.HasHash = true
184			}
185		}
186	
187		return artifacts, nil
188	}
