440	// readTranscriptFromObjectTree reads and reassembles a transcript from a git tree object.
441	// Handles both chunked and non-chunked transcripts. Uses agent-aware reassembly
442	// when agentType is known, falling back to JSONL reassembly otherwise.
443	func readTranscriptFromObjectTree(tree *object.Tree, agentType types.AgentType) ([]byte, error) {
444		var chunkFiles []string
445		var hasBaseFile bool
446	
447		for _, entry := range tree.Entries {
448			if entry.Name == paths.V2RawTranscriptFileName {
449				hasBaseFile = true
450			}
451			if strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
452				idx := agent.ParseChunkIndex(entry.Name, paths.V2RawTranscriptFileName)
453				if idx > 0 {
454					chunkFiles = append(chunkFiles, entry.Name)
455				}
456			}
457		}
458	
459		// If chunk files exist, reassemble all chunks (base file is chunk 0)
460		if len(chunkFiles) > 0 {
461			chunkFiles = agent.SortChunkFiles(chunkFiles, paths.V2RawTranscriptFileName)
462			if hasBaseFile {
463				chunkFiles = append([]string{paths.V2RawTranscriptFileName}, chunkFiles...)
464			}
465	
466			var chunks [][]byte
467			for _, chunkFile := range chunkFiles {
468				file, fileErr := tree.File(chunkFile)
469				if fileErr != nil {
470					continue
471				}
472				content, contentErr := file.Contents()
473				if contentErr != nil {
474					continue
475				}
476				chunks = append(chunks, []byte(content))
477			}
478	
479			if len(chunks) > 0 {
480				result, reassembleErr := agent.ReassembleTranscript(chunks, agentType)
481				if reassembleErr != nil {
482					return nil, fmt.Errorf("failed to reassemble transcript: %w", reassembleErr)
483				}
484				return result, nil
485			}
486		}
487	
488		// No chunk files — read base file directly (non-chunked transcript)
489		if hasBaseFile {
490			file, err := tree.File(paths.V2RawTranscriptFileName)
491			if err == nil {
492				content, contentErr := file.Contents()
493				if contentErr == nil {
494					return []byte(content), nil
495				}
496			}
497		}
498	
499		return nil, nil

