97			return err
98		}
99	
100		repairResult, repairErr := strategy.RepairV2GenerationMetadata(ctx)
101		if repairErr != nil {
102			return fmt.Errorf("failed to repair archived v2 generation metadata: %w", repairErr)
103		}
104		printV2GenerationRepairResult(out, cmd.ErrOrStderr(), repairResult)
105	
106		printMigrateCompletion(out, result)
107		fmt.Fprintln(out, "Note: V2 checkpoints are stored as custom refs under refs/entire/checkpoints/v2/*, not as a branch visible in the GitHub UI.")
108		fmt.Fprintf(out, "To inspect pushed v2 checkpoint refs locally, run: git ls-remote %s \"refs/entire/checkpoints/v2/*\"\n", migrateRemoteName)
109		fmt.Fprintln(out, `You may also open a checkpoint's details in the Entire web app and click the "session logs" link to view the log files and metadata.`)
