188	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, progressOut io.Writer, force bool) (*migrateResult, error) {
189		v1List, err := v1Store.ListCommitted(ctx)
190		if err != nil {
191			return nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
192		}
193	
194		if len(v1List) == 0 {
195			return &migrateResult{}, nil
196		}
197	
198		sortMigratableCheckpoints(v1List)
199		total := len(v1List)
200		result := &migrateResult{total: total}
201		progress := startProgressBar(progressOut, "Migrating checkpoints", total)
202		defer progress.Finish()
203	
204		_, fullCurrentRefErr := repo.Reference(plumbing.ReferenceName(paths.V2FullCurrentRefName), true)
205		fullCurrentExistsBefore := fullCurrentRefErr == nil
206	
207		packer := newGenerationPacker(repo, v2Store)
208	
209		for _, info := range v1List {
210			fullCheckpoint, outcome, migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, force)
211			result.missingSessions += outcome.missingSessions
212			result.backfilledCompactTranscripts += outcome.backfilledCompactTranscripts
213			if outcome.compactTranscriptSkipped {
214				result.compactTranscriptSkipped++
215			}
216			if outcome.repaired {
217				result.repaired++
218			}
219	
220			if migrateErr != nil {
221				switch {
222				case errors.Is(migrateErr, errAlreadyMigrated):
223					logCheckpointMigrationSkip(ctx, info.CheckpointID, "already in v2", migrateErr)
224					result.skipped++
225				case errors.Is(migrateErr, errTranscriptNotGeneratable):
226					logCheckpointMigrationSkip(ctx, info.CheckpointID, "transcript.jsonl could not be generated", migrateErr)
227					result.skipped++
228				case errors.Is(migrateErr, errNoMigratableSessions):
229					logCheckpointMigrationSkip(ctx, info.CheckpointID, "no migratable v1 sessions", migrateErr)
230					result.skipped++
231				case errors.Is(migrateErr, errNoFullPackingNeeded):
232					result.migrated++
233				default:
234					logging.Error(ctx, "checkpoint migration failed",
235						slog.String("checkpoint_id", string(info.CheckpointID)),
236						slog.String("error", migrateErr.Error()),
237					)
238					result.failed++
239				}
240				progress.Increment()
241				continue
242			}
243	
244			if fullCheckpoint != nil {
245				if packErr := packer.add(ctx, *fullCheckpoint); packErr != nil {
246					return result, fmt.Errorf("failed to pack migrated raw transcripts: %w", packErr)
247				}
248			}
249			result.migrated++
250			progress.Increment()
251		}
252	
253		if err := packer.finalize(ctx, !fullCurrentExistsBefore); err != nil {
254			return result, fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
255		}
256	
257		return result, nil
258	}
