294	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
295		var outcome migrateCheckpointOutcome
296	
297		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
298		if err != nil {
299			return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
300		}
301	
302		if existing != nil && !force {
303			// Fast-path: when every session already has a compact transcript and
304			// /full/<n> artifacts, the repair branch below is a guaranteed no-op.
305			if v2CheckpointFullyMigrated(v2Store, info, existing) {
306				return nil, outcome, errAlreadyMigrated
307			}
308	
309			fullCheckpoint, queuedFullRepair, repairErr := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing)
310			if repairErr != nil {
311				return nil, outcome, repairErr
312			}
313			outcome.repaired = queuedFullRepair
314	
315			currentV2, readCurrentErr := v2Store.ReadCommitted(ctx, info.CheckpointID)
316			if readCurrentErr != nil {
317				return nil, outcome, fmt.Errorf("failed to re-read v2 checkpoint %s: %w", info.CheckpointID, readCurrentErr)
318			}
319			if currentV2 == nil {
320				return nil, outcome, fmt.Errorf("v2 checkpoint %s disappeared during migration", info.CheckpointID)
321			}
322	
323			// Clean up v1-named transcript files (full.jsonl, content_hash.txt) that older
324			// CLI versions may have written to /full/current before the rename to raw_transcript.
325			cleanupV1TranscriptFiles(ctx, repo, v2Store, info.CheckpointID, len(currentV2.Sessions))
326	
327			backfilled, backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, currentV2)
328			outcome.backfilledCompactTranscripts = backfilled
329			if !queuedFullRepair {
330				if backfillErr != nil {
331					return nil, outcome, backfillErr
332				}
333				return nil, outcome, errNoFullPackingNeeded
334			}
335			if errors.Is(backfillErr, errTranscriptNotGeneratable) {
336				outcome.compactTranscriptSkipped = true
337			}
338			if backfillErr != nil &&
339				!errors.Is(backfillErr, errAlreadyMigrated) &&
340				!errors.Is(backfillErr, errTranscriptNotGeneratable) {
341				return nil, outcome, backfillErr
342			}
343			return fullCheckpoint, outcome, nil
344		}
345	
346		if existing != nil && force {
347			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
348				return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
349			}
350		}
351	
