// RenameLegacyArtifactsInAllFullRefs walks every /full/* ref (current and
// every archived /full/<n>) and rewrites session subtrees so any pre-rename
// transcript filenames (full.jsonl, full.jsonl.NNN, content_hash.txt — see
// commit a3cd77122) are renamed to their current equivalents
// (raw_transcript, raw_transcript.NNN, raw_transcript_hash.txt). Blob
// hashes are preserved — only entry names change.
//
// A repo already on the current naming is a no-op (no commits created).
// Returns the number of session subtrees rewritten across all refs.
func (s *V2GitStore) RenameLegacyArtifactsInAllFullRefs(ctx context.Context, authorName, authorEmail string) (int, error) {
	refNames, err := s.fullRefSearchOrder()
	if err != nil {
		return 0, err
	}

	total := 0
	for _, refName := range refNames {
		n, err := s.renameLegacyArtifactsInFullRef(ctx, refName, authorName, authorEmail)
		if err != nil {
			return total, fmt.Errorf("rename legacy artifacts in %s: %w", refName, err)
		}
		total += n
	}
	return total, nil
}

func (s *V2GitStore) renameLegacyArtifactsInFullRef(ctx context.Context, refName plumbing.ReferenceName, authorName, authorEmail string) (int, error) {
	parentHash, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return 0, nil
		}
		return 0, err
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return 0, fmt.Errorf("read root tree: %w", err)
	}

	type sessionRewrite struct {
		pathSegments []string
		newEntries   []object.TreeEntry
		deleteNames  []string
	}
	var rewrites []sessionRewrite

	for _, shardEntry := range rootTree.Entries {
		if shardEntry.Mode != filemode.Dir || len(shardEntry.Name) != 2 {
			continue
		}
		shardTree, treeErr := s.repo.TreeObject(shardEntry.Hash)
		if treeErr != nil {
			continue
		}
		for _, cpEntry := range shardTree.Entries {
			if cpEntry.Mode != filemode.Dir {
				continue
			}
			cpTree, treeErr := s.repo.TreeObject(cpEntry.Hash)
			if treeErr != nil {
				continue
			}
			for _, sessionEntry := range cpTree.Entries {
				if sessionEntry.Mode != filemode.Dir {
					continue
				}
				if _, atoiErr := strconv.Atoi(sessionEntry.Name); atoiErr != nil {
					continue
				}
				sessionTree, treeErr := s.repo.TreeObject(sessionEntry.Hash)
				if treeErr != nil {
					continue
				}
				newEntries, deleteNames := planLegacyRenamesForSession(sessionTree.Entries)
				if len(deleteNames) == 0 {
					continue
				}
				rewrites = append(rewrites, sessionRewrite{
					pathSegments: []string{shardEntry.Name, cpEntry.Name, sessionEntry.Name},
					newEntries:   newEntries,
					deleteNames:  deleteNames,
				})
			}
		}
	}

	if len(rewrites) == 0 {
		return 0, nil
	}

	newRootHash := rootTreeHash
	for _, r := range rewrites {
		next, updateErr := UpdateSubtree(s.repo, newRootHash, r.pathSegments, r.newEntries,
			UpdateSubtreeOptions{
				MergeMode:   MergeKeepExisting,
				DeleteNames: r.deleteNames,
			})
		if updateErr != nil {
			return 0, fmt.Errorf("rewrite session %v: %w", r.pathSegments, updateErr)
		}
		newRootHash = next
	}

	if newRootHash == rootTreeHash {
		return 0, nil
	}

	msg := fmt.Sprintf("Rename legacy transcript filenames in %s\n", refName)
	if err := s.updateRef(ctx, refName, newRootHash, parentHash, msg, authorName, authorEmail); err != nil {
		return 0, err
	}
	return len(rewrites), nil
}

// planLegacyRenamesForSession inspects one session subtree's entries and
// returns the new entries to add (with current naming, pointing at the
// existing blob hashes) and the legacy entry names to delete. If both the
// legacy and the current name already exist for a given file, only the
// legacy entry is removed — the current entry is left untouched.
func planLegacyRenamesForSession(entries []object.TreeEntry) ([]object.TreeEntry, []string) {
	has := make(map[string]bool, len(entries))
	for _, e := range entries {
		has[e.Name] = true
	}

	var newEntries []object.TreeEntry
	var deleteNames []string
	for _, entry := range entries {
		var newName string
		switch {
		case entry.Name == paths.TranscriptFileName:
			newName = paths.V2RawTranscriptFileName
		case strings.HasPrefix(entry.Name, paths.TranscriptFileName+"."):
			newName = paths.V2RawTranscriptFileName + strings.TrimPrefix(entry.Name, paths.TranscriptFileName)
		case entry.Name == paths.ContentHashFileName:
			newName = paths.V2RawTranscriptHashFileName
		default:
			continue
		}
		deleteNames = append(deleteNames, entry.Name)
		if !has[newName] {
			newEntries = append(newEntries, object.TreeEntry{
				Name: newName,
				Mode: entry.Mode,
				Hash: entry.Hash,
			})
		}
	}
	return newEntries, deleteNames
}

