172	func (s *V2GitStore) ComputeGenerationTimestampsFromTrees(rootTreeHash plumbing.Hash, mainTree *object.Tree) (GenerationMetadata, bool, error) {
173		if rootTreeHash == plumbing.ZeroHash {
174			return GenerationMetadata{}, false, nil
175		}
176	
177		rootTree, err := s.repo.TreeObject(rootTreeHash)
178		if err != nil {
179			return GenerationMetadata{}, false, fmt.Errorf("failed to read generation tree: %w", err)
180		}
181	
182		var gen GenerationMetadata
183		found := false
184		missingCheckpointTimestamp := false
185		err = WalkCheckpointShards(s.repo, rootTree, func(cpID id.CheckpointID, cpTreeHash plumbing.Hash) error {
186			if mainTree != nil {
187				if cpGen, ok := s.checkpointTimestampRangeFromMain(mainTree, cpID); ok {
188					mergeGenerationRange(&gen, &found, cpGen)
189					return nil
190				}
191			}
192	
193			cpTree, treeErr := s.repo.TreeObject(cpTreeHash)
194			if treeErr != nil {
195				missingCheckpointTimestamp = true
196				return nil //nolint:nilerr // Skip unreadable checkpoint trees and fall back to generation.json.
197			}
198			if cpGen, ok := checkpointTimestampRangeFromFullTree(cpTree); ok {
199				mergeGenerationRange(&gen, &found, cpGen)
200				return nil
201			}
202			missingCheckpointTimestamp = true
203			return nil
